import{_ as a,o as s,c as t,a3 as n}from"./chunks/framework.B5WAEDB7.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/consistency-patterns.md","filePath":"core-concepts/consistency-patterns.md"}'),o={name:"core-concepts/consistency-patterns.md"};function r(i,e,c,l,h,d){return s(),t("div",null,[...e[0]||(e[0]=[n('<h2 id="consistency-patterns" tabindex="-1">Consistency patterns <a class="header-anchor" href="#consistency-patterns" aria-label="Permalink to &quot;Consistency patterns&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Consistency patterns.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p>With multiple copies of the same data, we are faced with options on how to synchronize them so clients have a consistent view of the data. Recall the definition of consistency from the <a href="/core-concepts/availability-vs-consistency.html#cap-theorem">CAP theorem</a> - Every read receives the most recent write or an error.</p><h3 id="weak-consistency" tabindex="-1">Weak consistency <a class="header-anchor" href="#weak-consistency" aria-label="Permalink to &quot;Weak consistency&quot;">​</a></h3><p>After a write, reads may or may not see it. A best effort approach is taken.</p><p>This approach is seen in systems such as memcached. Weak consistency works well in real time use cases such as VoIP, video chat, and realtime multiplayer games. For example, if you are on a phone call and lose reception for a few seconds, when you regain connection you do not hear what was spoken during connection loss.</p><h3 id="eventual-consistency" tabindex="-1">Eventual consistency <a class="header-anchor" href="#eventual-consistency" aria-label="Permalink to &quot;Eventual consistency&quot;">​</a></h3><p>After a write, reads will eventually see it (typically within milliseconds). Data is replicated asynchronously.</p><p>This approach is seen in systems such as DNS and email. Eventual consistency works well in highly available systems.</p><h3 id="strong-consistency" tabindex="-1">Strong consistency <a class="header-anchor" href="#strong-consistency" aria-label="Permalink to &quot;Strong consistency&quot;">​</a></h3><p>After a write, reads will see it. Data is replicated synchronously.</p><p>This approach is seen in file systems and RDBMSes. Strong consistency works well in systems that need transactions.</p><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="http://snarfed.org/transactions_across_datacenters_io.html" target="_blank" rel="noreferrer">Transactions across data centers</a></li></ul>',14)])])}const u=a(o,[["render",r]]);export{y as __pageData,u as default};
